import sys

data = sys.stdin.read().split()
s, t = data[0], data[1]
n = len(s)
start = tuple(s + t)
seen = {start}
stack = [start]
ok = False
while stack:
    cur = stack.pop()
    if cur[:n] == cur[n:]:
        ok = True
        break
    for i in range(2 * n):
        for j in range(i + 1, 2 * n):
            if cur[i] != cur[j]:
                nxt = list(cur)
                nxt[i], nxt[j] = nxt[j], nxt[i]
                nxt = tuple(nxt)
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
print('YES' if ok else 'NO')

